const loginElements = [{
  selector: 'login-page',
  name: '登录页面容器'
}, {
  selector: 'login-form',
  name: '登录表单'
}, {
  selector: 'login-username-form-item',
  name: '用户名字段'
}, {
  selector: 'login-username-input',
  name: '用户名输入框'
}, {
  selector: 'login-password-form-item',
  name: '密码字段'
}, {
  selector: 'login-password-input',
  name: '密码输入框'
}, {
  selector: 'login-remember-checkbox',
  name: '记住我复选框'
}, {
  selector: 'login-submit-button',
  name: '登录按钮'
}];
loginElements.forEach(el => {
  cy.get(`[data-cy="${el.selector}"]`).should('exist').and('be.visible');
  cy.log(`✅ ${el.name} (${el.selector}) 验证通过`);
});

// 输入用户名
cy.get('[data-cy="login-username-input"]').type('testuser').should('have.value', 'testuser');
// 输入密码
cy.get('[data-cy="login-password-input"]').type('testpassword').should('have.value', 'testpassword');
// 点击记住我
cy.get('[data-cy="login-remember-checkbox"]').click();

cy.visit('/login');
cy.wait(1000);
cy.get('[data-cy]').then($elements => {
  const violations = [];
  $elements.each((index, element) => {
    const dataCy = element.getAttribute('data-cy');
    if (dataCy) {
      // 检查是否包含大写字母或空格
      if (/[A-Z]/.test(dataCy)) {
        violations.push({
          attr: dataCy,
          issue: '包含大写字母'
        });
      }
      if (/\s/.test(dataCy)) {
        violations.push({
          attr: dataCy,
          issue: '包含空格'
        });
      }
      // 检查是否使用连字符
      if (!dataCy.includes('-')) {
        violations.push({
          attr: dataCy,
          issue: '未使用连字符分隔'
        });
      }
    }
  });
  if (violations.length > 0) {
    cy.log('⚠️ 发现命名规范违规:');
    violations.forEach(v => cy.log(`  - ${v.attr}: ${v.issue}`));
  } else {
    cy.log('✅ 所有data-cy属性符合命名规范');
  }
  expect(violations).to.have.length(0);
});

const pagesToCheck = ['/login', '/warehouse/zone'];
pagesToCheck.forEach(page => {
  cy.visit(page, {
    failOnStatusCode: false
  });
  cy.wait(1500);
  cy.get('[data-cy]').then($elements => {
    const dataCyValues = [];
    $elements.each((index, element) => {
      dataCyValues.push(element.getAttribute('data-cy'));
    });
    // 检查重复
    const duplicates = dataCyValues.filter((item, index) => dataCyValues.indexOf(item) !== index);
    if (duplicates.length > 0) {
      cy.log(`⚠️ ${page} 发现重复的data-cy属性: ${[...new Set(duplicates)].join(', ')}`);
    } else {
      cy.log(`✅ ${page} 所有data-cy属性唯一`);
    }
    expect([...new Set(duplicates)]).to.have.length(0);
  });
});

cy.visit('/warehouse/zone', {
  failOnStatusCode: false
});
cy.wait(1500);
const expectedElements = ['warehouse-zone-page', 'warehouse-zone-add-btn', 'zone-table', 'warehouse-zone-pagination'];
expectedElements.forEach(selector => {
  cy.get('body').then($body => {
    if ($body.find(`[data-cy="${selector}"]`).length > 0) {
      cy.get(`[data-cy="${selector}"]`).should('exist');
      cy.log(`✅ ${selector} 存在`);
    } else {
      cy.log(`⚠️ ${selector} 不存在`);
    }
  });
});

